.primaryButton {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 36px;
  padding: 0 18px;
  border: none;
  border-radius: 5px;
  background: var(--bw-calibration-blue);
  color: var(--bw-warm-cream);
  font-family: inherit;
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
