import { useEffect, useState, type FormEvent } from 'react';
import {
  fetchThreadPage,
  pageCount,
  type ThreadPage,
} from '../../lib/threads';
import type { MemberProfile } from '../../lib/session';
import { ThreadList } from './ThreadList';
import styles from './Messages.module.css';

interface MessagesProps {
  profile: MemberProfile;
  /** Inyectable para que los tests no dependan del reloj.
   *  F-137: `Date | undefined`, no solo `Date`. */
  now?: Date | undefined;
  /** Contrato público del shell. MSG-02 no existe en este alcance, así que la
   *  recibimos y no la cableamos. */
  onOpenThread?: (threadId: string) => void;
}

/**
 * Extrae el detalle del error de verdad (F-128). PostgREST no lanza siempre un
 * `Error`: a veces llega un objeto plano `{ code, message }`; `String(e)`
 * daría `[object Object]` y `e.message` no existiría.
 */
function errorDetail(cause: unknown): string {
  if (cause && typeof cause === 'object') {
    const record = cause as { code?: unknown; message?: unknown };
    const code = typeof record.code === 'string' ? record.code : undefined;
    const message =
      typeof record.message === 'string' ? record.message : undefined;
    const detail = [code, message]
      .filter(
        (part): part is string =>
          typeof part === 'string' && part.length > 0,
      )
      .join(' · ');
    if (detail.length > 0) return detail;
  }
  if (cause instanceof Error && cause.message) return cause.message;
  if (typeof cause === 'string' && cause) return cause;
  return '';
}

/**
 * MSG-01 · Lista de Hilos.
 *
 * Pantalla, no componente de presentación: posee el estado de búsqueda y de
 * página y consulta `fetchThreadPage` contra `profile.orgId`. El orden de las
 * filas es el que devuelve el servidor.
 */
export function Messages({ profile, now, onOpenThread }: MessagesProps) {
  const [query, setQuery] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [page, setPage] = useState(1);
  const [threadPage, setThreadPage] = useState<ThreadPage | null>(null);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState<unknown>(null);

  // Se ignora por diseño: abrir un hilo no lleva a ninguna parte hasta MSG-02.
  void onOpenThread;

  useEffect(() => {
    let alive = true;
    setLoading(true);
    setLoadError(null);

    fetchThreadPage({ orgId: profile.orgId, search: searchTerm, page })
      .then((result) => {
        if (alive) {
          setThreadPage(result);
          setLoading(false);
        }
      })
      .catch((cause: unknown) => {
        if (alive) {
          setLoadError(cause);
          setLoading(false);
        }
      });

    return () => {
      alive = false;
    };
  }, [profile.orgId, searchTerm, page]);

  const handleSearchSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setSearchTerm(query);
    setPage(1);
  };

  const openThreadStub = (_threadId: string) => {
    // MSG-02 no se construyó en este alcance: no hay pantalla a la que ir.
  };

  const snapshot = now ?? new Date();
  const pages = threadPage ? pageCount(threadPage.total) : 0;
  const alertDetail = loadError === null ? '' : errorDetail(loadError);

  return (
    <div className={styles.screen}>
      <p className={styles.eyebrow}>Módulo 04 · Mensajería E2EE</p>
      <h1 className={styles.pageTitle}>Hilos</h1>
      <p className={styles.pageSub}>
        Tus conversaciones con otros distribuidores. Todo el contenido está
        cifrado de extremo a extremo.
      </p>

      <div className={styles.e2eeBar} role="status">
        <i className="ti ti-lock" aria-hidden="true" />
        <span>
          E2EE activo · claves de sesión en memoria · solo se muestran
          metadatos
        </span>
      </div>

      <div className={styles.actionsBar}>
        <form
          role="search"
          className={styles.searchForm}
          onSubmit={handleSearchSubmit}
        >
          <i className={`ti ti-search ${styles.searchIcon}`} aria-hidden="true" />
          <label className={styles.srOnly} htmlFor="thread-search-input">
            Buscar por nombre de organización
          </label>
          <input
            id="thread-search-input"
            type="text"
            className={styles.searchInput}
            value={query}
            placeholder="Buscar por nombre de organización..."
            onChange={(event) => setQuery(event.target.value)}
          />
          <button type="submit" className={styles.srOnly} tabIndex={-1}>
            Buscar
          </button>
        </form>

        {/* DIR-01 no está entre las pantallas del MVP: el control existe, pero
            no lleva a ninguna parte y se pinta deshabilitado con su motivo. */}
        <button
          type="button"
          className={styles.primaryButton}
          disabled
          aria-describedby="directorio-scope-note"
        >
          <i className="ti ti-address-book" aria-hidden="true" />
          Nuevo contacto
        </button>

        {threadPage !== null && (
          <span data-testid="pag-info" className={styles.threadCount}>
            {threadPage.total.toLocaleString('es-ES')}{' '}
            {threadPage.total === 1 ? 'hilo' : 'hilos'}
            {' · Página '}
            {page.toLocaleString('es-ES')} de {pages.toLocaleString('es-ES')}
          </span>
        )}
      </div>

      <p
        id="directorio-scope-note"
        data-testid="directorio-scope"
        className={styles.actionScope}
      >
        Este botón abre DIR-01, que no se entrega en este MVP.
      </p>

      {loadError !== null && (
        <div role="alert" className={styles.errorAlert}>
          <i className={styles.errorIcon} aria-hidden="true" />
          <span>
            <span className={styles.errorTitle}>
              No se pudieron cargar los hilos.
            </span>
            {alertDetail !== '' && (
              <span className={styles.errorDetail}>{alertDetail}</span>
            )}
          </span>
        </div>
      )}

      {loadError === null && loading && threadPage === null && (
        <p className={styles.loadingText}>Cargando hilos…</p>
      )}

      {loadError === null && threadPage !== null && (
        <>
          <ThreadList
            threads={threadPage.threads}
            now={snapshot}
            onOpen={openThreadStub}
          />
          {pages > 1 && (
            <nav
              className={styles.pagination}
              aria-label="Paginación de hilos"
            >
              <button
                type="button"
                className={styles.pageButton}
                disabled={page <= 1}
                onClick={() => setPage(page - 1)}
                aria-label="Página anterior"
              >
                ‹
              </button>
              {Array.from({ length: pages }, (_, index) => index + 1).map(
                (number) => (
                  <button
                    key={number}
                    type="button"
                    className={
                      number === page
                        ? `${styles.pageButton} ${styles.pageButtonActive}`
                        : styles.pageButton
                    }
                    aria-current={number === page ? 'page' : undefined}
                    onClick={() => setPage(number)}
                  >
                    {number.toLocaleString('es-ES')}
                  </button>
                ),
              )}
              <button
                type="button"
                className={styles.pageButton}
                disabled={page >= pages}
                onClick={() => setPage(page + 1)}
                aria-label="Página siguiente"
              >
                ›
              </button>
            </nav>
          )}
        </>
      )}
    </div>
  );
}

