import {
  previewLabel,
  relativeTime,
  stateTone,
  type StateTone,
  type ThreadSummary,
} from '../../lib/threads';
import styles from './ThreadList.module.css';

interface ThreadListProps {
  threads: ThreadSummary[];
  /** Inyectable para los tests. F-137: se declara `Date | undefined` para no
   *  rechazar un `undefined` que llega con `exactOptionalPropertyTypes`. */
  now?: Date | undefined;
  onOpen: (threadId: string) => void;
}

/**
 * Tono -> clase CSS del módulo. El tipo de cada entrada es `string | undefined`
 * (F-143): `noUncheckedIndexedAccess` no garantiza que la clase exista en el
 * CSS, y el `?? ''` se aplica al consumir la entrada.
 */
const TONE_CLASS: Record<StateTone, string | undefined> = {
  neutral: styles.neutral,
  info: styles.info,
  warn: styles.warn,
  success: styles.success,
  closed: styles.closed,
};

/**
 * Lista de hilos de MSG-01. Presentacional: no consulta datos ni pagina.
 *
 * F-131: la fila es un `<li>` y lo que se pulsa es un `<button>` DENTRO de él.
 * El `<li>` conserva así su rol `listitem` y el botón lleva el nombre
 * accesible del hilo, sin duplicar botones.
 *
 * F-141: el estado vacío no vive dentro de un `<ul>`; si la lista no tiene
 * filas no debe quedar ningún `listitem` en el documento.
 */
export function ThreadList({ threads, now, onOpen }: ThreadListProps) {
  if (threads.length === 0) {
    return (
      <div className={styles.emptyState}>
        <p className={styles.emptyText}>
          Todavía no tienes ninguna conversación. Usa el Directorio para
          contactar con otras organizaciones.
        </p>
        <div className={styles.emptyActions}>
          <button type="button" className={styles.directoryButton} disabled>
            Ir al Directorio
          </button>
          <p className={styles.scopeNote}>El Directorio queda fuera del MVP.</p>
        </div>
      </div>
    );
  }

  const snapshot = now ?? new Date();

  return (
    <ul className={styles.threadList}>
      {threads.map((thread) => {
        const toneClass = TONE_CLASS[stateTone(thread.state)] ?? '';
        return (
          <li key={thread.id} className={styles.rowItem}>
            <button
              type="button"
              className={styles.rowButton}
              onClick={() => onOpen(thread.id)}
            >
              <span className={styles.rowTop}>
                <span className={styles.orgName}>{thread.counterpartyName}</span>
                {thread.counterpartyCountry.length > 0 && (
                  <span className={styles.countryBadge}>
                    {thread.counterpartyCountry}
                  </span>
                )}
              </span>
              <span className={styles.rowMeta}>
                <time dateTime={thread.lastItemAt} className={styles.timestamp}>
                  {relativeTime(thread.lastItemAt, snapshot)}
                </time>
              </span>
              <span className={styles.rowBottom}>
                <span className={styles.preview}>
                  {previewLabel(thread.lastItem)}
                </span>
                <span className={`${styles.stateBadge} ${toneClass}`}>
                  {thread.state}
                </span>
              </span>
            </button>
          </li>
        );
      })}
    </ul>
  );
}

